CREATE INDEX sessions_bot_owner_idx ON sessions(bot_conversation_id,collaboration_state,bot_joined_at);
CREATE INDEX agents_kind_status_idx ON agents(kind,status,name);

CREATE TRIGGER agent_index_insert BEFORE INSERT ON agents WHEN NEW.content_sha256 IS NOT NULL AND (NEW.kind NOT IN ('coordinator','project') OR NEW.bot_id IS NOT NULL OR NEW.project_id IS NOT NULL OR NEW.source_template_id IS NOT NULL OR length(NEW.content_sha256)!=64) BEGIN SELECT RAISE(ABORT,'new agents are independent Markdown definitions'); END;
CREATE TRIGGER agent_identity_update BEFORE UPDATE ON agents WHEN OLD.kind IS NOT NULL AND (NEW.kind IS NOT OLD.kind OR NEW.bot_id IS NOT OLD.bot_id OR NEW.project_id IS NOT OLD.project_id OR NEW.source_template_id IS NOT OLD.source_template_id) BEGIN SELECT RAISE(ABORT,'Agent identity and independent ownership are fixed'); END;
CREATE TRIGGER agent_status_index_update BEFORE UPDATE OF content_sha256 ON agents WHEN NEW.content_sha256 IS NOT NULL AND length(NEW.content_sha256)!=64 BEGIN SELECT RAISE(ABORT,'invalid Agent Markdown digest'); END;


CREATE TRIGGER session_parent_fixed BEFORE UPDATE ON sessions WHEN OLD.bot_conversation_id IS NOT NULL AND NEW.bot_conversation_id IS NOT OLD.bot_conversation_id BEGIN SELECT RAISE(ABORT,'session parent is fixed'); END;
CREATE TRIGGER session_agent_fixed BEFORE UPDATE ON sessions WHEN OLD.agent_id IS NOT NULL AND NEW.agent_id IS NOT OLD.agent_id BEGIN SELECT RAISE(ABORT,'session role identity is fixed'); END;
CREATE TRIGGER session_role_insert BEFORE INSERT ON sessions WHEN NEW.agent_id IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM agents WHERE id=NEW.agent_id AND kind='project' AND status='active' AND revision>=json_extract(NEW.agent_snapshot_json,'$.revision')) OR json_extract(NEW.agent_snapshot_json,'$.agentId') IS NOT NEW.agent_id OR json_extract(NEW.agent_snapshot_json,'$.contentSha256') IS NULL) BEGIN SELECT RAISE(ABORT,'invalid project role'); END;
CREATE TRIGGER session_role_update BEFORE UPDATE OF agent_id,agent_snapshot_json ON sessions WHEN json_extract(NEW.agent_snapshot_json,'$.agentId') IS NOT NEW.agent_id OR NOT EXISTS(SELECT 1 FROM agents WHERE id=NEW.agent_id AND kind='project' AND status='active' AND revision>=json_extract(NEW.agent_snapshot_json,'$.revision')) BEGIN SELECT RAISE(ABORT,'invalid project role'); END;
CREATE TRIGGER session_snapshot_started BEFORE UPDATE OF agent_snapshot_json ON sessions WHEN NEW.agent_snapshot_json IS NOT OLD.agent_snapshot_json AND (NEW.agent_id IS NOT OLD.agent_id OR json_extract(NEW.agent_snapshot_json,'$.agentId') IS NOT NEW.agent_id OR EXISTS(SELECT 1 FROM project_calls WHERE session_id=OLD.id AND status IN ('accepted','working','unknown'))) BEGIN SELECT RAISE(ABORT,'session Agent version requires a stable same-identity adoption'); END;
CREATE TRIGGER session_assignment_busy BEFORE UPDATE OF assignment ON sessions WHEN NEW.assignment IS NOT OLD.assignment AND EXISTS(SELECT 1 FROM project_calls WHERE session_id=OLD.id AND status IN ('accepted','working','unknown')) BEGIN SELECT RAISE(ABORT,'session has pending project call'); END;

CREATE TRIGGER bots_role_insert BEFORE INSERT ON bots WHEN NEW.coordinator_agent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM agents WHERE id=NEW.coordinator_agent_id AND kind='coordinator' AND content_sha256 IS NOT NULL AND status='active' AND revision>=json_extract(NEW.coordinator_agent_snapshot_json,'$.revision')) BEGIN SELECT RAISE(ABORT,'invalid coordinator'); END;
CREATE TRIGGER bots_role_update BEFORE UPDATE OF coordinator_agent_id,coordinator_agent_snapshot_json ON bots WHEN NEW.coordinator_agent_id IS NOT NULL AND (json_extract(NEW.coordinator_agent_snapshot_json,'$.agentId') IS NOT NEW.coordinator_agent_id OR NOT EXISTS(SELECT 1 FROM agents WHERE id=NEW.coordinator_agent_id AND kind='coordinator' AND content_sha256 IS NOT NULL AND status='active' AND revision>=json_extract(NEW.coordinator_agent_snapshot_json,'$.revision'))) BEGIN SELECT RAISE(ABORT,'invalid coordinator'); END;
CREATE TRIGGER conversation_role_insert BEFORE INSERT ON bot_conversations WHEN NEW.coordinator_agent_id IS NULL OR json_extract(NEW.coordinator_agent_snapshot_json,'$.agentId') IS NOT NEW.coordinator_agent_id OR NOT EXISTS(SELECT 1 FROM agents WHERE id=NEW.coordinator_agent_id AND kind='coordinator' AND content_sha256 IS NOT NULL AND status='active' AND revision>=json_extract(NEW.coordinator_agent_snapshot_json,'$.revision')) BEGIN SELECT RAISE(ABORT,'coordinator required'); END;
CREATE TRIGGER conversation_role_update BEFORE UPDATE OF coordinator_agent_snapshot_json ON bot_conversations WHEN json_extract(NEW.coordinator_agent_snapshot_json,'$.agentId') IS NOT NEW.coordinator_agent_id OR NOT EXISTS(SELECT 1 FROM agents WHERE id=NEW.coordinator_agent_id AND kind='coordinator' AND content_sha256 IS NOT NULL AND status='active' AND revision>=json_extract(NEW.coordinator_agent_snapshot_json,'$.revision')) OR EXISTS(SELECT 1 FROM project_calls WHERE conversation_id=OLD.id AND status IN ('accepted','working','unknown')) BEGIN SELECT RAISE(ABORT,'coordinator Agent version requires a stable same-identity adoption'); END;
